def fill_replaces_bg(grid):
    """Fill color replaces background, frame stays as-is"""
    rows, cols = len(grid), len(grid[0])
    output = [[0] * cols for _ in range(rows)]

    # Find frame
    all_colors = {}
    for r in range(rows):
        for c in range(cols):
            color = grid[r][c]
            if color != 0:
                if color not in all_colors:
                    all_colors[color] = {'rmin': float('inf'), 'rmax': float('-inf'), 'cmin': float('inf'), 'cmax': float('-inf')}
                all_colors[color]['rmin'] = min(all_colors[color]['rmin'], r)
                all_colors[color]['rmax'] = max(all_colors[color]['rmax'], r)
                all_colors[color]['cmin'] = min(all_colors[color]['cmin'], c)
                all_colors[color]['cmax'] = max(all_colors[color]['cmax'], c)

    sorted_colors = sorted(all_colors.items(), 
        key=lambda x: (x[1]['rmax']-x[1]['rmin']+1)*(x[1]['cmax']-x[1]['cmin']+1), reverse=True)
    frame_color = sorted_colors[0][0]
    fill_color = sorted_colors[1][0]

    rmin_f, rmax_f, cmin_f, cmax_f = all_colors[frame_color]['rmin'], all_colors[frame_color]['rmax'], \
                                      all_colors[frame_color]['cmin'], all_colors[frame_color]['cmax']

    # Copy input
    for r in range(rows):
        for c in range(cols):
            output[r][c] = grid[r][c]

    # Extend 2 cells, fill background with fill_color
    border_rmin, border_rmax = rmin_f - 2, rmax_f + 2
    border_cmin, border_cmax = cmin_f - 2, cmax_f + 2

    for r in range(border_rmin, border_rmax + 1):
        for c in range(border_cmin, border_cmax + 1):
